-- productos2 = <nuevo codigo>-<producto>
-- Mapa nuevo codigo -> CODIGO_PRODUCTO (los repetidos traen el mismo valor, no afecta)
IF OBJECT_ID('tempdb..#map') IS NOT NULL DROP TABLE #map;
CREATE TABLE #map (nuevo VARCHAR(20), cod VARCHAR(30));





-- UPDATE: productos2 = <nuevo codigo>-<producto>
UPDATE p
SET    p.productos2 = m.nuevo + '-' + p.producto
FROM   productos p
INNER JOIN (SELECT cod, MIN(nuevo) AS nuevo FROM #map GROUP BY cod) m
        ON m.cod = p.CODIGO_PRODUCTO;

DROP TABLE #map;
